import pytest

from shoplib.cart import Cart


def test_add_and_subtotal():
    cart = Cart()
    cart.add("A", 250, 2)
    cart.add("B", 1000)
    assert cart.line_total("A") == 500
    assert cart.subtotal() == 1500


def test_add_same_sku_merges():
    cart = Cart()
    cart.add("A", 250, 2)
    cart.add("A", 250, 3)
    assert cart.line_total("A") == 1250


def test_bad_qty():
    with pytest.raises(ValueError):
        Cart().add("A", 250, 0)
from shoplib.discounts import Coupon, apply_coupon


def test_percent():
    assert apply_coupon(1000, Coupon("TEN", "percent", 10)) == 900


def test_fixed_never_negative():
    assert apply_coupon(300, Coupon("FIVE", "fixed", 500)) == 0
